using System.Collections.Generic;using UnityEngine;namespace FallenForest.World{public sealed class ForestScatterer:MonoBehaviour{[SerializeField]private GameObject[] treePrefabs,grassPrefabs;[SerializeField]private Terrain terrain;[SerializeField]private int treeCount=3250,grassClumpCount=9000,seed=228117;[SerializeField]private float edgePadding=14f,clearStartRadius=9f;[SerializeField]private Transform startPoint,generatedRoot;[SerializeField]private bool generateOnStart;private readonly List<GameObject> spawned=new();private void Start(){if(generateOnStart)Generate();}[ContextMenu("Generate Forest")]public void Generate(){Clear();if(terrain==null||treePrefabs==null||treePrefabs.Length==0)return;if(generatedRoot==null){GameObject root=new("GeneratedForest");root.transform.SetParent(transform,false);generatedRoot=root.transform;}Random.State old=Random.state;Random.InitState(seed);Vector3 tp=terrain.transform.position,size=terrain.terrainData.size;for(int i=0;i<treeCount;i++){Vector3 p=RandomPoint(tp,size);if(startPoint!=null&&Vector3.Distance(new Vector3(p.x,0,p.z),new Vector3(startPoint.position.x,0,startPoint.position.z))<clearStartRadius){i--;continue;}p.y=terrain.SampleHeight(p)+tp.y;GameObject prefab=treePrefabs[Random.Range(0,treePrefabs.Length)];if(prefab==null)continue;GameObject go=Instantiate(prefab,p,Quaternion.Euler(0,Random.Range(0,360f),0),generatedRoot);float s=Random.Range(.82f,1.25f);go.transform.localScale*=s;spawned.Add(go);}if(grassPrefabs!=null&&grassPrefabs.Length>0)for(int i=0;i<grassClumpCount;i++){Vector3 p=RandomPoint(tp,size);p.y=terrain.SampleHeight(p)+tp.y;GameObject prefab=grassPrefabs[Random.Range(0,grassPrefabs.Length)];if(prefab==null)continue;GameObject go=Instantiate(prefab,p,Quaternion.Euler(0,Random.Range(0,360f),0),generatedRoot);go.transform.localScale*=Random.Range(.7f,1.4f);spawned.Add(go);}Random.state=old;}private Vector3 RandomPoint(Vector3 p,Vector3 s)=>new(Random.Range(p.x+edgePadding,p.x+s.x-edgePadding),0,Random.Range(p.z+edgePadding,p.z+s.z-edgePadding));[ContextMenu("Clear Forest")]public void Clear(){for(int i=spawned.Count-1;i>=0;i--)if(spawned[i]!=null)DestroyImmediate(spawned[i]);spawned.Clear();if(generatedRoot!=null)while(generatedRoot.childCount>0)DestroyImmediate(generatedRoot.GetChild(0).gameObject);}}}
